boolean apply(Connection db, Payment p) throws SQLException {
    try (var insert = db.prepareStatement(
            "INSERT INTO processed_payments (idempotency_key, account_id, amount_cents) VALUES (?, ?, ?)")) {
        insert.setString(1, p.idempotencyKey());
        insert.setString(2, p.account());
        insert.setLong(3, p.amountCents());
        insert.executeUpdate();
    } catch (SQLIntegrityConstraintViolationException duplicate) {  // ORA-00001
        db.rollback();
        return false;
    }
    try (var update = db.prepareStatement(
            "UPDATE balances SET balance_cents = balance_cents + ? WHERE account_id = ?")) {
        update.setLong(1, p.amountCents());
        update.setString(2, p.account());
        update.executeUpdate();
    }
    db.commit();
    return true;
}

